});

test('returns DATE_INVALID for invalid date format', () => {
  const testCases = [
    '2026-10-7',
    '26-10-07',
    '2026/10/07',
    '2026.10.07',
    '10-07-2026',
    '2026-13-01',
    '2026-10',
    '10/07/2026',
    '',
  ];

  for (const date of testCases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert(result.ok === false, `Expected DATE_INVALID for date: ${date}`);
    assert.equal(result.error, 'DATE_INVALID');
  }
});

test('returns DATE_INVALID for invalid dates (e.g., Feb 30)', () => {
  const testCases = [
    '2026-02-30',
    '2026-04-31',
    '2026-02-29',
  ];

  for (const date of testCases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
