import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount } from '../src/invoices.js';

test('creates a valid invoice with one line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok === true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);
  assert.deepEqual(result.value.lines[0], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 5,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 0,
  });
});

test('creates a valid invoice with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'COPY-HOUR', qty: 3 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert(result.ok === true);
  assert.equal(result.value.lines.length, 3);
  assert.deepEqual(result.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 2,
    unitPrice: 8500,
    vatRate: 21,
    discountPercent: 0,
  });
  assert.deepEqual(result.value.lines[2], {
    sku: 'WORKSHOP-DAY',
    name: 'Brand workshop (day, VAT exempt)',
    qty: 1,
    unitPrice: 60000,
    vatRate: 0,
    discountPercent: 0,
  });
});

