test('createInvoice returns DISCOUNT_INVALID for out-of-range discounts', () => {
  const testCases = [
    { sku: 'DEV-HOUR', qty: 5, discountPercent: -1 },
    { sku: 'DEV-HOUR', qty: 5, discountPercent: 101 },
    { sku: 'DEV-HOUR', qty: 5, discountPercent: 'ten' },
    { sku: 'DEV-HOUR', qty: 5, discountPercent: null },
  ];

  for (const line of testCases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [line],
    });
    assert(result.ok === false, `Expected DISCOUNT_INVALID for: ${JSON.stringify(line)}`);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  }
});

test('lineDiscount calculates discount correctly', () => {
