    { line: { qty: 5, unitPrice: 9500, discountPercent: 100 }, expected: 47500 },
    { line: { qty: 10, unitPrice: 1000, discountPercent: 25 }, expected: 2500 },
  ];

  for (const { line, expected } of testCases) {
