test('invoiceTotals with multiple line discounts', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 10 },
      { qty: 2, unitPrice: 8500, discountPercent: 20 },
      { qty: 1, unitPrice: 60000, discountPercent: 5 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = 47500 + 17000 + 60000;
  const discount = 4750 + 3400 + 3000;
  assert.deepEqual(totals, {
    subtotal,
    discount,
    total: subtotal - discount,
  });
});

